import json
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = "http://localhost:8080"
LOG = {"status_counts": {}, "retries": 0, "token_refreshes": 0, "rate_limit_waits": 0}


def note(code):
    LOG["status_counts"][str(code)] = LOG["status_counts"].get(str(code), 0) + 1


def request(path, method="GET", token=None):
    headers = {}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    req = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            note(resp.status)
            return resp.status, dict(resp.headers), resp.read()
    except urllib.error.HTTPError as e:
        note(e.code)
        return e.code, dict(e.headers), e.read()
    except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
        note("network")
        return None, {}, str(e).encode()


class Client:
    def __init__(self):
        self.token = None

    def get_token(self):
        LOG["token_refreshes"] += 1
        for attempt in range(20):
            code, headers, body = request("/token", method="POST")
            if code == 200:
                self.token = json.loads(body)["token"]
                return
            wait_for(code, headers, attempt)
        raise SystemExit("could not obtain token")

    def get(self, path):
        # Retries until a usable 200 response, honouring 429 Retry-After and refreshing on 401.
        if self.token is None:
            self.get_token()
        attempt = 0
        while True:
            attempt += 1
            if attempt > 200:
                raise SystemExit(f"giving up on {path}")
            code, headers, body = request(path, token=self.token)
            if code == 200:
                return json.loads(body)
            if code == 401:
                self.get_token()
                continue
            if code == 404:
                return None
            LOG["retries"] += 1
            wait_for(code, headers, attempt)


def wait_for(code, headers, attempt):
    if code == 429:
        ra = headers.get("Retry-After")
        LOG["rate_limit_waits"] += 1
        try:
            delay = float(ra)
        except (TypeError, ValueError):
            delay = 2.0
        print(f"429 Retry-After={ra!r}; sleeping {delay}s", file=sys.stderr)
        time.sleep(delay)
    else:
        time.sleep(min(2 ** min(attempt, 5) * 0.25, 10))


def cents_after_discount(amount_cents, pct):
    # Half-up rounding per order, exact via Decimal.
    d = (Decimal(amount_cents) * (Decimal(100) - Decimal(pct)) / Decimal(100))
    return int(d.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def main():
    client = Client()
    window_start = datetime(2025, 3, 1, tzinfo=timezone.utc)
    window_end = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive, i.e. through 31 May inclusive

    seen = {}           # id -> order record (first listing)
    duplicates = 0
    dup_conflicts = []  # duplicate listings whose contents differ from the first listing
    all_statuses = {}
    page = 1
    total_pages = None
    orders_seen_raw = 0

    while True:
        data = client.get(f"/orders?page={page}")
        if data is None:
            raise SystemExit(f"page {page} returned 404")
        total_pages = data["total_pages"]
        for item in data["items"]:
            orders_seen_raw += 1
            oid = item["id"]
            all_statuses[item["status"]] = all_statuses.get(item["status"], 0) + 1
            if oid in seen:
                duplicates += 1
                if seen[oid] != item:
                    dup_conflicts.append((oid, seen[oid], item))
            else:
                seen[oid] = item
        print(f"page {page}/{total_pages} items={len(data['items'])}", file=sys.stderr)
        if data.get("next") is None or page >= total_pages:
            break
        page += 1

    customers = {}
    total = 0
    by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
    count = 0
    excluded_by_date = 0

    for oid, o in seen.items():
        if o["status"] != "shipped":
            continue
        ts = datetime.fromisoformat(o["placed_at"]).astimezone(timezone.utc)
        if not (window_start <= ts < window_end):
            excluded_by_date += 1
            continue
        cid = o["customer_id"]
        if cid not in customers:
            c = client.get(f"/customers/{cid}")
            if c is None:
                raise SystemExit(f"unknown customer {cid} on order {oid}")
            customers[cid] = c
        c = customers[cid]
        amt = cents_after_discount(o["amount_cents"], c["discount_pct"])
        total += amt
        by_region[c["region"]] += amt
        count += 1

    result = {
        "total_cents": total,
        "order_count": count,
        "duplicates_skipped": duplicates,
        "by_region": by_region,
    }
    print(json.dumps(result, indent=2))
    print("---diagnostics---", file=sys.stderr)
    print(json.dumps({
        "pages": total_pages,
        "raw_listings": orders_seen_raw,
        "distinct_orders": len(seen),
        "duplicate_listings": duplicates,
        "duplicate_conflicts": dup_conflicts[:5],
        "conflict_count": len(dup_conflicts),
        "statuses": all_statuses,
        "excluded_shipped_outside_range": excluded_by_date,
        "customers_fetched": len(customers),
        "log": LOG,
    }, indent=2, default=str), file=sys.stderr)


if __name__ == "__main__":
    main()

